{
  "title": "A slower Kyoto day",
  "summary": "A gentle day with two unhurried sights and two proper meals, all in one corner of the city.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "The golden pavilion stays, and slower means you actually look at it instead of past it.",
      "note_voice": "Shoes off, phone down, eyes up."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "One temple is enough for a slow day, but this hall of a thousand statues earns its hour.",
      "note_voice": "The deer will cope without you. The blossoms won't wait."
    },
    {
      "poi_id": "p19",
      "kind": "meal",
      "must_do_id": null,
      "note": "A calm vegan lunch near the temple, so nobody has to pick around a menu.",
      "note_voice": "Tentative usually means a dentist. Worth one message."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "An evening wander down Pontocho, where the lanterns do the work and you just walk.",
      "note_voice": "The deer will cope without you. The blossoms won't wait."
    },
    {
      "poi_id": "p18",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with a show of an omelette, and vegetarian plates for the crew.",
      "note_voice": "Shoes off, phone down, eyes up."
    }
  ]
}
